import { NextRequest } from "next/server";

import { fail, ok } from "@/lib/api-response";
import { setSessionCookie, signSession } from "@/lib/auth";
import { usersCol } from "@/lib/collections";
import { ensureIndexes } from "@/lib/indexes";
import { verifyPassword } from "@/lib/password";
import { getClientIp, rateLimit } from "@/lib/rate-limit";
import { loginSchema } from "@/lib/validators/auth";

export async function POST(req: NextRequest) {
  const limit = rateLimit({
    key: `login:${getClientIp(req)}`,
    limit: 10,
    windowMs: 60_000,
  });

  if (!limit.allowed) {
    return fail("Too many requests", 429);
  }

  let body: unknown;

  try {
    body = await req.json();
  } catch {
    return fail("Invalid request", 400);
  }

  const parsed = loginSchema.safeParse(body);

  if (!parsed.success) {
    return fail("Invalid request", 400);
  }

  try {
    await ensureIndexes();

    const userCollection = await usersCol();
    const user = await userCollection.findOne({
      email: parsed.data.email,
    });

    if (!user) {
      return fail("Invalid credentials", 401);
    }

    if (!user.verified) {
      return fail("Please verify your email", 403);
    }

    const passwordMatches = await verifyPassword(
      parsed.data.password,
      user.password,
    );

    if (!passwordMatches) {
      return fail("Invalid credentials", 401);
    }

    const now = new Date();

    await userCollection.updateOne(
      { _id: user._id },
      {
        $set: {
          lastLoginAt: now,
          updatedAt: now,
        },
      },
    );

    const token = await signSession({
      userId: user._id.toString(),
      role: user.isAdmin === 1 ? "admin" : "student",
      isAdmin: user.isAdmin === 1 ? 1 : 0,
      tier: user.tier,
    });

    await setSessionCookie(token, parsed.data.remember ?? true);

    return ok({
      user: {
        id: user._id.toString(),
        name: user.name,
        email: user.email,
        role: user.isAdmin === 1 ? "admin" : "student",
        isAdmin: user.isAdmin,
        tier: user.tier,
        verified: user.verified,
        avatarUrl: user.avatarUrl ?? null,
      },
    });
  } catch (error) {
    console.error("Login error", error);
    return fail("Server error", 500);
  }
}
